/** Container admission only. Pixels are generated by the original native
 * sampler; the codec stores exact f32 words, signed integer residuals and
 * original-word exceptions. No normalized parameter is approximated. */
export function gradientPhaseFieldLayout(words:Uint32Array) {
 if(!(words.buffer instanceof ArrayBuffer)||words.length<8||words[0]!==0x47504631||words[5]!==2048||
    words.length%2048||words.byteLength>32*1024*1024||!words[1]||!words[2]||words[1]*words[2]>4_194_304||
    words[3]!==Math.ceil(words[1]/8)||words[4]!==Math.ceil(words[2]/8)||words[6]>words.length||words[7]!==0)
  throw Error('Invalid native gradient phase field')
 const head=8+words[3]*words[4],end=words[6]
 if(head>end)throw Error('Invalid gradient phase directory')
 const pop=(v:number)=>{v-=v>>>1&0x55555555;v=(v&0x33333333)+(v>>>2&0x33333333);return (((v+(v>>>4))&0x0f0f0f0f)*0x01010101)>>>24}
 for(let i=8;i<head;i++){
  const entry=words[i],mode=entry>>>30,at=entry&0x3fffffff
  if(at<head||at>=end)throw Error('Invalid gradient phase block')
  const length=mode===3?1:mode===2?256:(mode===0?114:162)+3*(pop(words[at])+pop(words[at+1]))
  if(at+length>end)throw Error('Truncated gradient phase block')
 }
 return {width:2048,height:words.length/2048,sourceWidth:words[1],sourceHeight:words[2]}
}

export const gradientPhaseDecodeWgsl=`
fn gpfAxisTuple(point:vec2<i32>,phase:u32,shape:vec2<i32>)->vec4<f32>{
 var q=point;if(shape.x==1){q.x=0;}if(shape.y==1){q.y=0;}
 if(any(q<vec2<i32>(0))||any(q>=shape)){return vec4<f32>(0);}
 let index=phase*u32(shape.x*shape.y)+u32(q.y*shape.x+q.x);let width=textureDimensions(sourceD,0).x;
 return textureLoad(sourceD,vec2<i32>(i32(index%width),i32(index/width)),0);
}
fn gpfWord(index:u32)->u32{
 let width=textureDimensions(sourceD,0).x;
 let bytes=vec4<u32>(round(textureLoad(sourceD,vec2<i32>(i32(index%width),i32(index/width)),0)*255.));
 return bytes.x|(bytes.y<<8u)|(bytes.z<<16u)|(bytes.w<<24u);
}
fn gpfEntry(point:vec2<i32>)->vec3<u32>{
 let size=vec2<i32>(i32(gpfWord(1u)),i32(gpfWord(2u)));
 let q=vec2<u32>(clamp(point,vec2<i32>(0),size-1));
 let entry=gpfWord(8u+(q.y/8u)*gpfWord(3u)+q.x/8u);
 return vec3<u32>(entry>>30u,entry&0x3fffffffu,(q.y%8u)*8u+q.x%8u);
}
fn gpfBase(point:vec2<i32>)->u32{
 let e=gpfEntry(point);
 if(e.x==3u){return gpfWord(e.y);}
 if(e.x==2u){return gpfWord(e.y+e.z*4u);}
 return gpfWord(e.y+2u+e.z);
}
fn gpfCode(point:vec2<i32>,phase:u32)->u32{
 let e=gpfEntry(point);let mode=e.x;let at=e.y;let pixel=e.z;
 if(mode==3u){return gpfWord(at);}
 if(mode==2u){return gpfWord(at+pixel*4u+phase);}
 let q=gpfWord(at+2u+pixel);if(phase==0u){return q;}
 let bits=select(8u,16u,mode==1u);let deltaWords=select(48u,96u,mode==1u);
 let mask=gpfWord(at+pixel/32u);let bit=pixel%32u;
 if((mask&(1u<<bit))!=0u){
  var rank=countOneBits(mask&((1u<<bit)-1u));if(pixel>=32u){rank=rank+countOneBits(gpfWord(at));}
  return gpfWord(at+2u+64u+deltaWords+rank*3u+phase-1u);
 }
 let index=pixel*3u+phase-1u;let perWord=32u/bits;
 let packed=gpfWord(at+2u+64u+index/perWord)>>((index%perWord)*bits);
 let residual=bitcast<i32>(packed<<(32u-bits))>>(32u-bits);
 let base=bitcast<i32>(q);
 let dy=bitcast<i32>(gpfBase(point+vec2<i32>(0,1)))-base;
 var prediction=0;
 if(phase==2u){
  let dl=bitcast<i32>(gpfBase(point+vec2<i32>(-1,0)))-base;
  let dly=bitcast<i32>(gpfBase(point+vec2<i32>(-1,1)))-base;
  prediction=(dl+dly+3*dy)/8;
 }else{
  let dx=bitcast<i32>(gpfBase(point+vec2<i32>(1,0)))-base;
  let dxy=bitcast<i32>(gpfBase(point+vec2<i32>(1,1)))-base;
  if(phase==1u){prediction=(3*dx+dy+dxy)/8;}else{prediction=(dx+9*dy+3*dxy)/16;}
 }
 return q+bitcast<u32>(prediction+residual);
}
fn gpfTuple(point:vec2<i32>,phase:u32)->vec4<f32>{
 let size=vec2<i32>(i32(gpfWord(1u)),i32(gpfWord(2u)));
 if(any(point<vec2<i32>(0))||any(point>=size)){return vec4<f32>(0);}
 let code=gpfCode(point,phase);
 if(code==0x40a00000u){return vec4<f32>(-1.,-1.,0.,0.);}
 if(code>=0x40000000u&&code<=0x40800000u){let i=f32((code-0x40000000u)>>22u);return vec4<f32>(i,i,0.,0.);}
 let i=f32(code>>31u);return vec4<f32>(i,i+1.,bitcast<f32>(code&0x7fffffffu),0.);
}
`
export function gradientPhaseSource(source:string){
 for(const [first,last] of [
  ['let dimensions:vec2<i32>=vec2<i32>(textureDimensions(sourceD,0));','let grid:vec4<f32>=textureLoad(sourceD,address,0);'],
  ['let dimensions=vec2<i32>(textureDimensions(sourceD,0));','let grid=textureLoad(sourceD,address,0);'],
 ]){
  const start=source.indexOf(first),end=source.indexOf(last,start)
  if(start<0||end<start||source.indexOf(last,end+last.length)>=0)throw Error('Gradient field source contract changed')
  const legacy=source.slice(start,end+last.length).replace(last,'grid=textureLoad(sourceD,address,0);')
  source=source.slice(0,start)+'var grid:vec4<f32>;if(u(47).w==10.){let t=fixedLinear(p+u(46).xy);grid=select(vec4<f32>(0.,1.,t,0.),vec4<f32>(0.),t==0.);}else if(u(47).w==9.||u(47).w==11.){grid=sourcePlaneTuple(address,u(47).yz);}else if(u(47).w==8.){grid=linearCornerTuple(address,u(47).yz);}else if(u(47).w>0.5){grid=gpfTuple(address,u32(u(47).w)-1u);}else if(u(47).w< -0.5){grid=gpfAxisTuple(address,u32(-u(47).w)-1u,vec2<i32>(u(47).yz));}else{'+legacy+'}\n'+source.slice(end+last.length)
 }
 return `fn sourcePlaneTuple(address:vec2<i32>,size:vec2<f32>)->vec4<f32>{
  let v=textureLoad(sourceD,vec2<i32>(0,0),0);
  let uv=clamp(vec2<f32>(address)/max(vec2<f32>(1.),size-1.),vec2<f32>(0.),vec2<f32>(1.));
  var t=mix(mix(v.x,v.y,uv.x),mix(v.z,v.w,uv.x),uv.y);
  if(u(47).w==11.){let w=textureLoad(sourceD,vec2<i32>(1,0),0);t=length(vec2<f32>(t,mix(mix(w.x,w.y,uv.x),mix(w.z,w.w,uv.x),uv.y)));}
  t=clamp(t,0.,1.);
  let count=u32(u(8).w);
  for(var index=0u;index<count;index++){
    let end=gradientStop(index).x;
    if(t<=end){
      if(index==0u){return vec4<f32>(0.);}
      let start=gradientStop(index-1u).x;
      return vec4<f32>(f32(index-1u),f32(index),(t-start)/(end-start),0.);
    }
  }
  return vec4<f32>(f32(count-1u),f32(count-1u),0.,0.);
}
fn linearCornerTuple(address:vec2<i32>,size:vec2<f32>)->vec4<f32>{
  let uv=clamp(vec2<f32>(address)/max(vec2<f32>(1.),size-1.),vec2<f32>(0.),vec2<f32>(1.));
  let first=textureLoad(sourceD,vec2<i32>(0,0),0);
  let top=mix(first.z,textureLoad(sourceD,vec2<i32>(1,0),0).z,uv.x);
  let bottom=mix(textureLoad(sourceD,vec2<i32>(0,1),0).z,textureLoad(sourceD,vec2<i32>(1,1),0).z,uv.x);
  return vec4<f32>(first.xy,mix(top,bottom,uv.y),0.);
}\n`+gradientPhaseDecodeWgsl+source
}
